// Reflect point p over line through origin with direction (dx,dy)
Point reflect(Point p, double dx, double dy) {
    double len2 = dx*dx+dy*dy;
    double dot = p.x*dx+p.y*dy;
    Point r;
    r.x = 2*dot*dx/len2 - p.x;
    r.y = 2*dot*dy/len2 - p.y;
    return r;
}

int findPoint(Point p) {
    for(int i=0;i<n;i++) {
        if(fabs(pts[i].x-p.x)<EPS && fabs(pts[i].y-p.y)<EPS) return i;
    }
    return -1;
}

int checkAxis(double cx, double cy, double dx, double dy) {
    // Shift pts by centroid, reflect, check
    for(int i=0;i<n;i++) {
        Point p = {pts[i].x-cx, pts[i].y-cy};
        Point r = reflect(p, dx, dy);
        r.x += cx; r.y += cy;
        if(findPoint(r)<0) return 0;
    }
    return 1;
}

