    static boolean symmetricPolygon(Point[] p) {
        int n = p.length;
        if (n < 3) return false;
        if (!isSimplePolygon(p)) return false;

        // Try all possible symmetry axes
        for (int i = 0; i < n; i++) {
            // Case 1: axis through vertex i and midpoint of opposite edge (odd n)
            // Case 2: axis through midpoints of opposite edges (even n)
            int j = (i + 1) % n;
            double mx = (p[i].x + p[j].x) / 2;
            double my = (p[i].y + p[j].y) / 2;
            if (checkAxis(p, p[i], new Point(mx, my))) return true;
            if (checkAxis(p, new Point(mx, my), p[(i + n/2) % n])) return true;
        }
        return false;
    }

    static boolean checkAxis(Point[] p, Point a, Point b) {
        int n = p.length;
        // Axis defined by line through a and b
        double dx = b.x - a.x;
        double dy = b.y - a.y;
        for (int i = 0; i < n; i++) {
            Point p1 = p[i];
            Point p2 = p[(n - i) % n];
            // Reflect p1 over axis, should match p2
            double t = ((p1.x - a.x) * dx + (p1.y - a.y) * dy) / (dx * dx + dy * dy);
            double rx = 2 * (a.x + t * dx) - p1.x;
            double ry = 2 * (a.y + t * dy) - p1.y;
            if (Math.abs(rx - p2.x) > 1e-9 || Math.abs(ry - p2.y) > 1e-9) return false;
        }
        return true;
    }

    static boolean isSimplePolygon(Point[] p) {
        int n = p.length;
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                int ni = (i + 1) % n;
                int nj = (j + 1) % n;
                if (i == nj || j == ni) continue;
                if (segmentsIntersect(p[i], p[ni], p[j], p[nj])) return false;
            }
        }
        return true;
    }

    static boolean segmentsIntersect(Point a, Point b, Point c, Point d) {
        double o1 = cross(a, b, c);
        double o2 = cross(a, b, d);
        double o3 = cross(c, d, a);
        double o4 = cross(c, d, b);
        if (o1 * o2 < 0 && o3 * o4 < 0) return true;
        if (o1 == 0 && onSegment(a, b, c)) return true;
        if (o2 == 0 && onSegment(a, b, d)) return true;
        if (o3 == 0 && onSegment(c, d, a)) return true;
        if (o4 == 0 && onSegment(c, d, b)) return true;
        return false;
    }

    static double cross(Point a, Point b, Point c) {
        return (b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x);
    }

    static boolean onSegment(Point a, Point b, Point p) {
        return Math.min(a.x, b.x) <= p.x && p.x <= Math.max(a.x, b.x) &&
               Math.min(a.y, b.y) <= p.y && p.y <= Math.max(a.y, b.y);
    }
}

