import java.io.*;
import java.util.*;

/*
 * Line-symmetric polygon check
 *
 * Key fact:
 * A set of points can be the vertex set of a line-symmetric simple polygon
 * iff the set itself is symmetric with respect to some line.
 *
 * For a finite point set with line symmetry:
 * - Its centroid lies on the symmetry axis.
 * - After translating points by subtracting the centroid, the symmetry axis
 *   passes through the origin.
 * - For any point p not on the axis, its mirror p' satisfies p + p' parallel
 *   to the axis. Therefore, for a correct axis direction u, all vectors
 *   (p + matchedMirror(p)) are parallel to u.
 *
 * Practical criterion used here:
 * 1) Compute centroid C.
 * 2) Translate all points: qi = n * pi - sum(p), so centroid becomes origin
 *    and all coordinates remain integral.
 * 3) If all translated points are (0,0), any line through origin works.
 * 4) Otherwise, choose any nonzero translated point a. The symmetry axis must be
 *    either parallel or perpendicular to a reflected relation, and can be derived
 *    from pairing a with some point b of equal squared length:
 *      axis direction is parallel to (a + b), unless a + b = 0,
 *      in which case axis is perpendicular to a.
 *    Try all such candidates.
 * 5) For a candidate axis direction u, each point q must have its reflection
 *    q' = 2*proj_u(q) - q. Using integer arithmetic with rational coordinates:
 *      q' = ( 2 (q·u) u - (u·u) q ) / (u·u)
 *    We verify reflected points exist in the set.
 *
 * Complexity: O(n^2 log n), sufficient for typical constraints.
 */
public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    static class Point {
        long x, y;
        Point(long x, long y) { this.x = x; this.y = y; }
    }

    static long gcd(long a, long b) {
        a = Math.abs(a);
        b = Math.abs(b);
        while (b != 0) {
            long t = a % b;
            a = b;
            b = t;
        }
        return a;
    }

    static String key(long x, long y) {
        return x + "#" + y;
    }

    static boolean checkAxis(Point[] q, HashSet<String> set, long ux, long uy) {
        if (ux == 0 && uy == 0) return false;
        long uu = ux * ux + uy * uy;

        for (Point p : q) {
            long dot = p.x * ux + p.y * uy;

            // reflected point numerator:
            // rx_num = 2*dot*ux - uu*p.x
            // ry_num = 2*dot*uy - uu*p.y
            long rxNum = 2L * dot * ux - uu * p.x;
            long ryNum = 2L * dot * uy - uu * p.y;

            if (rxNum % uu != 0 || ryNum % uu != 0) return false;
            long rx = rxNum / uu;
            long ry = ryNum / uu;

            if (!set.contains(key(rx, ry))) return false;
        }
        return true;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        StringBuilder out = new StringBuilder();

        while (true) {
            int n;
            try {
                n = fs.nextInt();
            } catch (Exception e) {
                break;
            }
            if (n == 0) break;

            Point[] p = new Point[n];
            long sx = 0, sy = 0;
            for (int i = 0; i < n; i++) {
                long x = fs.nextLong();
                long y = fs.nextLong();
                p[i] = new Point(x, y);
                sx += x;
                sy += y;
            }

            Point[] q = new Point[n];
            HashSet<String> set = new HashSet<>(n * 2 + 1);
            boolean allZero = true;
            for (int i = 0; i < n; i++) {
                long x = n * p[i].x - sx;
                long y = n * p[i].y - sy;
                q[i] = new Point(x, y);
                set.add(key(x, y));
                if (x != 0 || y != 0) allZero = false;
            }

            boolean ok = false;

            if (allZero) {
                ok = true;
            } else {
                int idx = -1;
                for (int i = 0; i < n; i++) {
                    if (q[i].x != 0 || q[i].y != 0) {
                        idx = i;
                        break;
                    }
                }

                Point a = q[idx];
                long lenA = a.x * a.x + a.y * a.y;

                HashSet<String> tried = new HashSet<>();

                for (int i = 0; i < n && !ok; i++) {
                    Point b = q[i];
                    long lenB = b.x * b.x + b.y * b.y;
                    if (lenB != lenA) continue;

                    long ux, uy;
                    long sxv = a.x + b.x;
                    long syv = a.y + b.y;

                    if (sxv == 0 && syv == 0) {
                        // axis perpendicular to a
                        ux = -a.y;
                        uy = a.x;
                    } else {
                        ux = sxv;
                        uy = syv;
                    }

                    long g = gcd(ux, uy);
                    ux /= g;
                    uy /= g;
                    if (ux < 0 || (ux == 0 && uy < 0)) {
                        ux = -ux;
                        uy = -uy;
                    }

                    String k = key(ux, uy);
                    if (tried.contains(k)) continue;
                    tried.add(k);

                    if (checkAxis(q, set, ux, uy)) {
                        ok = true;
                    }
                }
            }

            out.append(ok ? "Yes" : "No").append('\n');
        }

        System.out.print(out.toString());
    }
}

