struct Point {
    double x, y;
    Point() : x(0), y(0) {}
    Point(double x_, double y_) : x(x_), y(y_) {}
    Point operator+(const Point &p) const { return Point(x + p.x, y + p.y); }
    Point operator-(const Point &p) const { return Point(x - p.x, y - p.y); }
    Point operator*(double s) const { return Point(x * s, y * s); }
    double dot(const Point &p) const { return x * p.x + y * p.y; }
    double cross(const Point &p) const { return x * p.y - y * p.x; }
    double norm2() const { return x * x + y * y; }
    double dist2(const Point &p) const { return (*this - p).norm2(); }
};

const double EPS = 1e-9;

bool is_on_segment(Point a, Point b, Point p) {
    if (fabs((b - a).cross(p - a)) > EPS) return false;
    double dot = (p - a).dot(p - b);
    return dot <= EPS;
}

bool segments_intersect(Point a1, Point a2, Point b1, Point b2) {
    double c1 = (a2 - a1).cross(b1 - a1);
    double c2 = (a2 - a1).cross(b2 - a1);
    double c3 = (b2 - b1).cross(a1 - b1);
    double c4 = (b2 - b1).cross(a2 - b1);
    if (c1 * c2 < -EPS && c3 * c4 < -EPS) return true;
    if (fabs(c1) < EPS && is_on_segment(a1, a2, b1)) return true;
    if (fabs(c2) < EPS && is_on_segment(a1, a2, b2)) return true;
    if (fabs(c3) < EPS && is_on_segment(b1, b2, a1)) return true;
    if (fabs(c4) < EPS && is_on_segment(b1, b2, a2)) return true;
    return false;
}

bool valid_polygon(const vector<Point> &p) {
    int n = p.size();
    if (n < 3) return false;
    for (int i = 0; i < n; i++) {
        int j = (i + 1) % n;
        for (int k = 0; k < n; k++) {
            int l = (k + 1) % n;
            if (i == k || i == l || j == k || j == l) continue;
            if (segments_intersect(p[i], p[j], p[k], p[l])) return false;
        }
    }
    return true;
}

Point reflect(Point p, Point a, Point b) {
    Point dir = b - a;
    double t = (p - a).dot(dir) / dir.norm2();
    Point proj = a + dir * t;
    return proj * 2 - p;
}

bool check_symmetry(const vector<Point> &poly, Point a, Point b) {
    int n = poly.size();
    vector<bool> used(n, false);
    for (int i = 0; i < n; i++) {
        if (used[i]) continue;
        Point refl = reflect(poly[i], a, b);
        bool found = false;
        for (int j = 0; j < n; j++) {
            if (used[j]) continue;
            if (poly[j].dist2(refl) < EPS) {
                used[i] = used[j] = true;
                found = true;
                break;
            }
        }
        if (!found) return false;
    }
    return true;
}

bool solve_case(vector<Point> &pts) {
    int n = pts.size();
    if (!valid_polygon(pts)) return false;
    // Try axes through two vertices
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            if (check_symmetry(pts, pts[i], pts[j])) return true;
        }
    }
    // Try axes through midpoints of two edges
    for (int i = 0; i < n; i++) {
        Point a = (pts[i] + pts[(i + 1) % n]) * 0.5;
        for (int j = i + 1; j < n; j++) {
            Point b = (pts[j] + pts[(j + 1) % n]) * 0.5;
            if (check_symmetry(pts, a, b)) return true;
        }
    }
    return false;
}

