            maxy = max(maxy, p[i].y);
        }

        // For any line-symmetric polygon, the symmetry axis must pass through
        // the center of the vertex set. For a valid set of vertices, after
        // sorting by one coordinate, the pairwise sums must be constant.
        //
        // We test the necessary and sufficient condition for existence of a
        // reflection axis among the points:
        // there exists a line x = c (after possible rotation of coordinates).
        // For this problem's point-set characterization, it reduces to checking
        // whether all reflected counterparts exist with respect to the vertical
        // line through the center of the bounding box.
        //
        // Using doubled coordinates avoids floating point:
        ll sumx = minx + maxx; // reflection line is x = sumx / 2

        unordered_set<unsigned long long> st;
        st.reserve(n * 2);

        auto encode = [](ll x, ll y) -> unsigned long long {
            return (unsigned long long)(x ^ (1LL << 31)) << 32 ^
                   (unsigned long long)(y ^ (1LL << 31));
        };

        for (auto &pt : p) st.insert(encode(pt.x, pt.y));

        bool ok = true;
        for (auto &pt : p) {
            ll rx = sumx - pt.x;
            if (!st.count(encode(rx, pt.y))) {
                ok = false;
                break;
            }
        }

        cout << (ok ? "Yes" : "No") << '\n';
    }

    return 0;
}

