def points_equal(p1, p2):
    return abs(p1[0] - p2[0]) < 1e-9 and abs(p1[1] - p2[1]) < 1e-9

def collinear(p1, p2, p3):
    return abs((p2[1] - p1[1]) * (p3[0] - p2[0]) - (p3[1] - p2[1]) * (p2[0] - p1[0])) < 1e-9

def orientation(p, q, r):
    val = (q[1] - p[1]) * (r[0] - q[0]) - (q[0] - p[0]) * (r[1] - q[1])
    if abs(val) < 1e-9:
        return 0
    return 1 if val > 0 else -1

def segments_intersect(p1, q1, p2, q2):
    o1 = orientation(p1, q1, p2)
    o2 = orientation(p1, q1, q2)
    o3 = orientation(p2, q2, p1)
    o4 = orientation(p2, q2, q1)
    if o1 != o2 and o3 != o4:
        return True
    # collinear cases ignored since problem says no touching except endpoints
    return False

def simple_polygon(pts):
    n = len(pts)
    for i in range(n):
        for j in range(i + 1, n):
            if (j == (i + 1) % n) or (i == (j + 1) % n):
                continue
            if segments_intersect(pts[i], pts[(i + 1) % n], pts[j], pts[(j + 1) % n]):
                return False
    return True

def check_symmetry(pts):
    n = len(pts)
    if n < 3:
        return False
    # Even n: axes through midpoints of opposite edges
    for i in range(n // 2):
        # Axis through midpoints of edge i->i+1 and opposite edge
        p1 = pts[i]
        p2 = pts[(i + 1) % n]
        q1 = pts[(i + n // 2) % n]
        q2 = pts[(i + n // 2 + 1) % n]
        mx1 = (p1[0] + p2[0]) / 2
        my1 = (p1[1] + p2[1]) / 2
        mx2 = (q1[0] + q2[0]) / 2
        my2 = (q1[1] + q2[1]) / 2
        # line through (mx1,my1) and (mx2,my2)
        a = my2 - my1
        b = mx1 - mx2
        c = -a * mx1 - b * my1
        if abs(a) < 1e-9 and abs(b) < 1e-9:
            continue
        ok = True
        for j in range(n):
            ref = reflect_point(pts[j], a, b, c)
            found = False
            for k in range(n):
                if points_equal(ref, pts[k]):
                    found = True
                    break
            if not found:
                ok = False
                break
        if ok and simple_polygon(pts):
            return True
    # Odd n: axes through a vertex and midpoint of opposite edge
    for i in range(n):
        v = pts[i]
        opp_mid = ((pts[(i + n // 2) % n][0] + pts[(i + n // 2 + 1) % n][0]) / 2,
                   (pts[(i + n // 2) % n][1] + pts[(i + n // 2 + 1) % n][1]) / 2)
        a = opp_mid[1] - v[1]
        b = v[0] - opp_mid[0]
        c = -a * v[0] - b * v[1]
        if abs(a) < 1e-9 and abs(b) < 1e-9:
            continue
        ok = True
        for j in range(n):
            ref = reflect_point(pts[j], a, b, c)
            found = False
            for k in range(n):
                if points_equal(ref, pts[k]):
                    found = True
                    break
            if not found:
                ok = False
                break
        if ok and simple_polygon(pts):
            return True
    return False

def main():
    data = sys.stdin.read().strip().split()
    idx = 0
    out_lines = []
    while idx < len(data):
        n = int(data[idx])
        idx += 1
        if n == 0:
            break
        pts = []
        for _ in range(n):
            x = float(data[idx])
            y = float(data[idx+1])
            idx += 2
            pts.append((x, y))
        if check_symmetry(pts):
            out_lines.append("YES")
        else:
            out_lines.append("NO")
    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    main()
